const files={"src/components/simulation/AtomicModelsCanvas.tsx": "'use client';\nimport { useRef, useEffect, useCallback, useState } from 'react';\nimport {\n  AtomicParams, AtomicModel,\n  generateThomsonElectrons, updateThomsonElectrons,\n  createAlphaParticle, updateAlphaParticle,\n  bohrEnergy, bohrRadius, bohrVelocity, transitionWavelength,\n  wavelengthToRGB, generateOrbitalSlice, radialDistribution,\n  type ThomsonElectron, type ScatteringParticle,\n} from '@/lib/physics/atomicModels';\nimport './atomic-models.css';\nimport {viewZoom} from '@/lib/physics/bohrWorkbench';\nimport {BohrRadiationLab} from './BohrRadiationLab';\n\ninterface Props {\n  params: AtomicParams;\n  isRunning: boolean;\n  isPaused: boolean;\n  onModelChange?: (model:AtomicModel)=>void;\n  onSpeedChange?: (speed:number)=>void;\n  onZoomChange?: (zoom:number)=>void;\n  onParamsChange?: (patch:Partial<AtomicParams>)=>void;\n  controls?: {run:()=>void;pause:()=>void;reset:()=>void};\n  interactive?: boolean;\n  onTick?: (stats: { \n    energy: number; \n    radius: number; \n    velocity: number; \n    n: number; \n    wavelength: number; \n    shellConfig: string \n  }) => void;\n}\n\nexport function AtomicModelsCanvas({ params, isRunning, isPaused, onTick, onModelChange, onSpeedChange, onZoomChange, onParamsChange, controls, interactive=true }: Props) {\n  const [viewReset,setViewReset]=useState(0);\n  const canvasPan=useRef({x:0,y:0});\n  const canvasDrag=useRef<{x:number;y:number;pan:{x:number;y:number}}|null>(null);\n  const canvasRef = useRef<HTMLCanvasElement | null>(null);\n  const wrapRef = useRef<HTMLDivElement | null>(null);\n  const rafRef = useRef<number>(0);\n  const lastFrameRef = useRef<number | null>(null);\n  const wallFrameRef=useRef<number|null>(null);\n  const wallDeltaRef=useRef(0);\n  const timeRef = useRef(0);\n  const lastTickRef = useRef(0);\n  const propsRef = useRef({ params, isRunning, isPaused, onTick });\n  propsRef.current = { params, isRunning, isPaused, onTick };\n\n  const thomsonRef = useRef<ThomsonElectron[]>([]);\n  const scatterRef = useRef<ScatteringParticle[]>([]);\n  const orbitalGridRef = useRef<{ x: number; z: number; prob: number }[][] | null>(null);\n  const orbitalCacheKeyRef = useRef('');\n  const quantumPulseRef = useRef(0);\n\n  const getFont = () => 'system-ui, sans-serif';\n\n  const resize = useCallback(() => {\n    const canvas = canvasRef.current;\n    const wrap = wrapRef.current;\n    if (!canvas || !wrap) return;\n    const dpr = window.devicePixelRatio || 1;\n    const rect = wrap.getBoundingClientRect();\n    const w = Math.floor(rect.width);\n    const h = Math.floor(rect.height);\n    if (canvas.width !== w * dpr || canvas.height !== h * dpr) {\n      canvas.width = w * dpr;\n      canvas.height = h * dpr;\n    }\n    canvas.style.width = w + 'px';\n    canvas.style.height = h + 'px';\n    const ctx = canvas.getContext('2d');\n    if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  }, []);\n\n  const drawThomson=useCallback((ctx:CanvasRenderingContext2D,cx:number,cy:number,w:number,h:number,dt:number,p:AtomicParams)=>{\n    const r=Math.max(15,Math.min(w-44,h-40)*.43);\n    const pudding=ctx.createRadialGradient(cx-r*.3,cy-r*.35,r*.05,cx,cy,r);\n    pudding.addColorStop(0,'#fff1d6');pudding.addColorStop(.55,'#fda4af');pudding.addColorStop(1,'#e11d48');\n    ctx.fillStyle=pudding;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();\n    ctx.strokeStyle='#9f1239';ctx.lineWidth=2.5;ctx.stroke();\n    // Plus signs are symbols for a continuous positive medium, not protons.\n    ctx.save();ctx.beginPath();ctx.arc(cx,cy,r-3,0,Math.PI*2);ctx.clip();\n    ctx.strokeStyle='#9f1239';ctx.lineWidth=1.6;\n    const spacing=Math.max(18,r/3.5);\n    for(let x=-r;x<=r;x+=spacing)for(let y=-r;y<=r;y+=spacing){if(x*x+y*y>r*r*.92)continue;const px=cx+x,py=cy+y;ctx.beginPath();ctx.moveTo(px-4,py);ctx.lineTo(px+4,py);ctx.moveTo(px,py-4);ctx.lineTo(px,py+4);ctx.stroke();}\n    if(p.showElectrons){\n      const plums=[[-.58,-.32],[-.1,-.64],[.42,-.4],[.66,.08],[.22,.45],[-.3,.56],[-.66,.15],[0,0]];\n      plums.forEach(([x,y],i)=>{const oscillation=Math.sin(timeRef.current*1.2+i)*.012*r,ex=cx+x*r+oscillation,ey=cy+y*r;\n        const radius=Math.max(6,Math.min(13,r*.075));ctx.fillStyle='#1e40af';ctx.strokeStyle='#eff6ff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ex,ey,radius,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(ex-radius*.4,ey);ctx.lineTo(ex+radius*.4,ey);ctx.stroke();});\n    }\n    ctx.restore();\n  },[]);\n\n  const drawRutherford = useCallback((ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, h: number, dt: number, p: AtomicParams) => {\n    const scale = Math.min(w-48, h-70) * 0.40;\n    const Z = p.protonCount || 79;\n    const A = Z + (p.neutronCount || 0);\n\n    if (p.showNucleus) {\n      const nuclearFm = 1.2 * Math.pow(A, 1 / 3);\n      const nr = Math.max(6, scale * 0.018 * Math.pow(A, 1 / 3));\n\n      // Coulomb field halo\n      const fieldR = nr * (3 + Math.log10(Math.max(Z, 1)));\n      const fieldGrad = ctx.createRadialGradient(cx, cy, nr, cx, cy, fieldR);\n      fieldGrad.addColorStop(0, `rgba(251,191,36,${0.08 + Z / 2000})`);\n      fieldGrad.addColorStop(0.6, 'rgba(251,191,36,0.03)');\n      fieldGrad.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = fieldGrad;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, fieldR, 0, Math.PI * 2); \n      ctx.fill();\n\n      // Dense core\n      const coreGlow = ctx.createRadialGradient(cx, cy, 0, cx, cy, nr * 2.5);\n      coreGlow.addColorStop(0, 'rgba(255,255,255,0.95)');\n      coreGlow.addColorStop(0.25, 'rgba(251,191,36,0.85)');\n      coreGlow.addColorStop(0.7, 'rgba(245,158,11,0.35)');\n      coreGlow.addColorStop(1, 'rgba(245,158,11,0)');\n      ctx.fillStyle = coreGlow;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr * 2.5, 0, Math.PI * 2); \n      ctx.fill();\n\n      ctx.fillStyle = '#b45309';\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.fill();\n\n      // Hard-sphere rim\n      ctx.strokeStyle = 'rgba(255,255,255,0.45)';\n      ctx.lineWidth = 1.5;\n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.stroke();\n\n      if (p.showLabels) {\n        ctx.fillStyle = '#b45309'; \n        ctx.font = 'bold 13px ' + getFont(); \n        ctx.textAlign = 'center';\n        ctx.fillText(`Nucleus  (${A}, ${Z})`, cx, cy + nr + 20);\n        ctx.fillStyle = '#92400e'; \n        ctx.font = '11px ' + getFont();\n        ctx.fillText(`r ≈ ${nuclearFm.toFixed(1)} fm`, cx, cy + nr + 36);\n      }\n    }\n\n    // Alpha spawn / update\n    if (dt > 0 && propsRef.current.isRunning && !propsRef.current.isPaused) {\n      if (Math.random() < 0.04 * p.speed) {\n        const b = (Math.random() - 0.5) * 400;\n        scatterRef.current.push(createAlphaParticle(b, p.alphaEnergy || 5));\n      }\n      scatterRef.current = scatterRef.current\n        .map(part => updateAlphaParticle(part, dt, p.protonCount))\n        .filter(part => part.active);\n    }\n\n    let recoilIntensity = 0;\n\n    scatterRef.current.forEach(part => {\n      const px = cx + part.x * scale * 0.0018;\n      const py = cy + part.y * scale * 0.0018;\n      const dx = px - cx;\n      const dy = py - cy;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n\n      if (part.active && dist < scale * 0.08) {\n        recoilIntensity = Math.max(recoilIntensity, 1 - dist / (scale * 0.08));\n      }\n\n      if (part.trail.length > 1) {\n        ctx.strokeStyle = 'rgba(190,18,60,0.7)'; \n        ctx.lineWidth = 1.5; \n        ctx.beginPath();\n        part.trail.forEach((pt, i) => {\n          const tx = cx + pt.x * scale * 0.0018;\n          const ty = cy + pt.y * scale * 0.0018;\n          if (i === 0) ctx.moveTo(tx, ty); else ctx.lineTo(tx, ty);\n        });\n        ctx.stroke();\n      }\n\n      const glow = ctx.createRadialGradient(px, py, 0, px, py, 10);\n      glow.addColorStop(0, 'rgba(244,63,94,0.6)'); \n      glow.addColorStop(1, 'rgba(244,63,94,0)');\n      ctx.fillStyle = glow; \n      ctx.beginPath(); \n      ctx.arc(px, py, 10, 0, Math.PI * 2); \n      ctx.fill();\n      ctx.fillStyle = '#f43f5e'; \n      ctx.beginPath(); \n      ctx.arc(px, py, 4, 0, Math.PI * 2); \n      ctx.fill();\n    });\n\n    // Recoil flash\n    if (recoilIntensity > 0) {\n      const flashNr = Math.max(6, scale * 0.018 * Math.pow(A, 1 / 3));\n      const flashR = flashNr * 5;\n      const flashGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, flashR);\n      flashGrad.addColorStop(0, `rgba(255,255,255,${recoilIntensity * 0.35})`);\n      flashGrad.addColorStop(0.4, `rgba(251,191,36,${recoilIntensity * 0.2})`);\n      flashGrad.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = flashGrad;\n      ctx.globalCompositeOperation = 'screen';\n      ctx.beginPath(); ctx.arc(cx, cy, flashR, 0, Math.PI * 2); ctx.fill();\n      ctx.globalCompositeOperation = 'source-over';\n    }\n\n  }, []);\n\n  const drawQuantum = useCallback((ctx: CanvasRenderingContext2D, cx: number, cy: number, w: number, h: number, dt: number, p: AtomicParams) => {\n    const scale = Math.min(w-48, h-70) * 0.32;\n    const n = p.nQuantum || 1, l = p.lQuantum || 0, m = p.mQuantum || 0, Z = p.protonCount || 1;\n    quantumPulseRef.current += dt * p.speed * 1.5;\n    if (p.showNucleus) {\n      const nr = 6, ng = ctx.createRadialGradient(cx, cy, 0, cx, cy, nr * 3);\n      ng.addColorStop(0, 'rgba(251,191,36,1)'); \n      ng.addColorStop(1, 'rgba(251,191,36,0)');\n      ctx.fillStyle = ng; \n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr * 3, 0, Math.PI * 2); \n      ctx.fill();\n      ctx.fillStyle = '#b45309'; \n      ctx.beginPath(); \n      ctx.arc(cx, cy, nr, 0, Math.PI * 2); \n      ctx.fill();\n      if (p.showLabels) { \n        ctx.fillStyle = '#b45309'; \n        ctx.font = 'bold 12px ' + getFont();\n        ctx.textAlign = 'center'; \n        ctx.fillText(`Z=${Z}`, cx, cy + nr + 18); \n      }\n    }\n    if (p.showProbability) {\n      const cacheKey = `${n},${l},${m},${scale}`;\n      if (orbitalCacheKeyRef.current !== cacheKey) { \n        orbitalGridRef.current = generateOrbitalSlice(n, l, m, 60); \n        orbitalCacheKeyRef.current = cacheKey; \n      }\n      const grid = orbitalGridRef.current;\n      if (grid) {\n        let maxP = 0; \n        grid.forEach(row => row.forEach(pt => { if (pt.prob > maxP) maxP = pt.prob; }));\n        const cellW = (scale * 2.6) / grid[0].length, cellH = (scale * 2.6) / grid.length;\n        const pulse = 0.7 + 0.3 * Math.sin(quantumPulseRef.current);\n        grid.forEach((row, ri) => { row.forEach((pt, ci) => { const prob = pt.prob / (maxP || 1); \n          if (prob < 0.02) return; \n          const px = cx + (pt.x / (10 * n)) * scale * 1.3, py = cy - (pt.z / (10 * n)) * scale * 1.3; \n          const alpha = Math.min(0.65, prob * 2.5 * pulse); \n          const hue = 200 + prob * 100 + Math.sin(quantumPulseRef.current + ci * 0.1) * 15; \n          ctx.fillStyle = `hsla(${hue}, 85%, 38%, ${alpha})`; \n          ctx.fillRect(px - cellW / 2, py - cellH / 2, cellW + 1, cellH + 1); }); \n        });\n        const scanY = cy - scale * 1.3 + ((Math.sin(quantumPulseRef.current * 0.5) * 0.5 + 0.5) * scale * 2.6);\n        ctx.strokeStyle = 'rgba(255,255,255,0.12)'; \n        ctx.lineWidth = 1; \n        ctx.beginPath(); \n        ctx.moveTo(cx - scale * 1.3, scanY); \n        ctx.lineTo(cx + scale * 1.3, scanY); \n        ctx.stroke();\n      }\n    }\n    if (onTick) { const now = performance.now(); \n      if (now - lastTickRef.current > 80) { \n        lastTickRef.current = now; onTick({ energy: bohrEnergy(n, Z), radius: bohrRadius(n, Z), velocity: 0, n, wavelength: 0, shellConfig: `${n}${['s','p','d','f'][l] || '?'}` });\n      } }\n  }, [onTick]);\n\n  const drawLoop = useCallback((timestamp?: number) => {\n    const canvas = canvasRef.current, wrap = wrapRef.current;\n    if (!canvas || !wrap) return;\n    const ctx = canvas.getContext('2d');\n    if (!ctx) return;\n    const s = propsRef.current, p = s.params;\n    resize();\n    const rect = wrap.getBoundingClientRect(), w = rect.width, h = rect.height;\n    if(w<1||h<1){rafRef.current=requestAnimationFrame(drawLoop);return;}\n    wallDeltaRef.current=timestamp===undefined?0:Math.max(0,Math.min(.05,(timestamp-(wallFrameRef.current??timestamp))/1000));wallFrameRef.current=timestamp??null;\n    let dt = 0;\n    if (s.isRunning && !s.isPaused && timestamp !== undefined) { if (lastFrameRef.current !== null) dt = Math.min((timestamp - lastFrameRef.current) / 1000, 0.05); \n      lastFrameRef.current = timestamp; } else { lastFrameRef.current = timestamp ?? null; }\n    if (dt > 0) timeRef.current += dt * p.speed;\n    const t = timeRef.current;\n    ctx.clearRect(0, 0, w, h); \n    ctx.fillStyle = '#f8fafc'; \n    ctx.fillRect(0, 0, w, h);\n\n    const cx = w / 2, cy = h / 2;\n    const magnification=viewZoom(p.zoom),drawingParams={...p,zoom:1};\n    ctx.save();ctx.translate(cx+canvasPan.current.x,cy+canvasPan.current.y);ctx.scale(magnification,magnification);ctx.translate(-cx,-cy);\n    switch (p.model) { case 'thomson': drawThomson(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      case 'rutherford': drawRutherford(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      case 'bohr': break;\n      case 'quantum': drawQuantum(ctx, cx, cy, w, h, dt, drawingParams); \n      break; \n      }\n    ctx.restore();\n    rafRef.current = requestAnimationFrame(drawLoop);\n  }, [resize, drawThomson, drawRutherford, drawQuantum]);\n\n  useEffect(() => { resize(); \n    rafRef.current = requestAnimationFrame(drawLoop); \n    const observer=new ResizeObserver(resize);if(wrapRef.current)observer.observe(wrapRef.current);\n    window.addEventListener('resize', resize); \n    return () => { observer.disconnect();cancelAnimationFrame(rafRef.current); \n      window.removeEventListener('resize', resize); \n    }; \n  }, [drawLoop, resize, params.model]);\n\n  const notes:Record<AtomicModel,{title:string;description:string;legend:string}>= {\n    thomson:{title:'Thomson · plum-pudding atom',description:'The pink pudding is a continuous sphere of positive charge. Blue negative electrons are the embedded plums. The + symbols mark the positive medium, not separate protons; this model has no nucleus.',legend:'Pink pudding: distributed positive charge · Blue plums: negative electrons'},\n    rutherford:{title:'Rutherford · nuclear scattering',description:'Most alpha particles pass through empty space; close approaches to the positively charged nucleus produce stronger deflections. Sizes are exaggerated.',legend:'Amber: nucleus · Rose trails: alpha particles'},\n    bohr:{title:'Bohr · quantised states',description:'A one-electron, hydrogen-like model. The electron absorbs energy to reach a higher n and emits a photon when it falls to a lower n. Jumps and shell spacing are schematic.',legend:'Blue: electron / occupied orbit · Amber: absorption · Violet: emission'},\n    quantum:{title:'Quantum · probability density',description:'Colour intensity represents the relative electron probability density in a 2D orbital slice. An orbital is not an electron path.',legend:'Darker colour: greater relative probability · Amber: nucleus'},\n  };\n  const note=notes[params.model];\n  const n=params.nQuantum||1,l=params.lQuantum||0;\n  const radial=Array.from({length:81},(_,i)=>{const r=i/80*10*n;return{r,d:radialDistribution(n,l,r)};});\n  const maxD=Math.max(...radial.map(p=>p.d),1e-12);\n  return <div className=\"af-atomic-view\" data-model={params.model}>\n    <header className=\"af-atomic-toolbar\"><strong>Atomic laboratory</strong>\n      {onModelChange&&interactive?<label>Model<select aria-label=\"Atomic model\" value={params.model} onChange={e=>onModelChange(e.target.value as AtomicModel)}><option value=\"thomson\">Thomson · plum pudding</option><option value=\"rutherford\">Rutherford · scattering</option><option value=\"bohr\">Bohr · radiation & states</option><option value=\"quantum\">Quantum · probability</option></select></label>:<span>{note.title}</span>}\n      {onSpeedChange&&interactive&&<label>Speed<select aria-label=\"Lesson speed\" value={params.speed} onChange={e=>onSpeedChange(Number(e.target.value))}>{Array.from(new Set([0,.5,1,1.5,2,3,params.speed])).sort((a,b)=>a-b).map(v=><option key={v} value={v}>{v}×</option>)}</select></label>}\n      {interactive&&onParamsChange&&params.model==='bohr'&&<label>Z<input aria-label=\"Nuclear charge Z\" type=\"number\" min=\"1\" max=\"92\" value={params.protonCount} onChange={e=>{const v=Number(e.target.value);if(Number.isInteger(v)&&v>=1&&v<=92)onParamsChange({protonCount:v});}}/></label>}\n      {interactive&&onZoomChange&&<label className=\"af-atomic-zoom\">Zoom<input aria-label=\"View zoom\" type=\"range\" min=\"0.3\" max=\"3\" step=\"0.1\" value={params.zoom} onChange={e=>onZoomChange(Number(e.target.value))}/><output>{viewZoom(params.zoom).toFixed(1)}×</output><button type=\"button\" onClick={()=>{onZoomChange(1);canvasPan.current={x:0,y:0};setViewReset(v=>v+1);}}>Fit</button></label>}\n      {interactive&&onParamsChange&&params.model==='bohr'&&<><label title=\"Chosen screening constant; Zeff=Z−σ. Hydrogenic approximation.\">σ<input aria-label=\"Screening constant\" type=\"number\" min=\"0\" max={Math.max(0,params.protonCount-1)} step=\"0.1\" disabled={params.protonCount<=1} value={params.screening??0} onChange={e=>{const v=Number(e.target.value);if(Number.isFinite(v)&&v>=0&&v<=params.protonCount-1)onParamsChange({screening:v});}}/></label>{params.showZeeman&&<label>B (T)<input aria-label=\"Magnetic field B\" type=\"range\" min=\"0\" max=\"5\" step=\"0.1\" value={params.magneticField} onChange={e=>onParamsChange({magneticField:Number(e.target.value)})}/><output>{params.magneticField.toFixed(1)}</output></label>}</>}\n      {interactive&&onParamsChange&&<details className=\"af-atomic-display\"><summary>Physics options</summary><div>{([['showOrbits','Orbits'],['showElectrons','Electrons'],['showNucleus','Nucleus'],['showEnergyLevels','Energy levels'],['showLabels','Labels'],...(params.model==='bohr'?[['showSpectrum','Spectrum'],['showSpin','Electron spin'],['showFineStructure','Fine structure'],['showZeeman','Zeeman effect']]:[]),...(params.model==='quantum'?[['showProbability','Probability cloud']]:[])] as [keyof AtomicParams,string][]).map(([key,label])=><label key={key}><input type=\"checkbox\" checked={!!params[key]} onChange={e=>onParamsChange({[key]:e.target.checked})}/>{label}</label>)}</div></details>}\n      {params.model!=='bohr'&&controls&&interactive&&<div className=\"af-atomic-playback\"><button type=\"button\" onClick={isRunning?controls.pause:controls.run}>{!isRunning?'Run':isPaused?'Resume':'Pause'}</button><button type=\"button\" onClick={controls.reset}>Reset</button></div>}\n    </header>\n    {params.model==='bohr'?<BohrRadiationLab params={params} onTick={onTick} interactive={interactive} viewReset={viewReset} isRunning={isRunning} isPaused={isPaused} controls={controls}/>:<>\n    <div className=\"af-atomic-layout\">\n      <div className=\"af-atomic-scene\" ref={wrapRef}>\n        <canvas ref={canvasRef} onPointerDown={e=>{canvasDrag.current={x:e.clientX,y:e.clientY,pan:{...canvasPan.current}};e.currentTarget.setPointerCapture(e.pointerId);}} onPointerMove={e=>{const d=canvasDrag.current;if(d)canvasPan.current={x:d.pan.x+e.clientX-d.x,y:d.pan.y+e.clientY-d.y};}} onPointerUp={()=>{canvasDrag.current=null;}} onPointerCancel={()=>{canvasDrag.current=null;}} role=\"img\" aria-label={`${note.title}. ${note.legend}.`} />\n      </div>\n    </div>\n    {params.showLabels&&<section className=\"af-atomic-notes\" aria-label=\"Model explanation\"><h3>{note.title}</h3><p>{note.description}</p><p className=\"af-atomic-legend\">{note.legend}</p><p className=\"af-atomic-caption\">Diagram sizes are schematic. Zoom magnifies the view; drag to pan and use Fit to restore framing.</p></section>}\n    {params.model==='quantum'&&params.showProbability&&<section className=\"af-atomic-notes\"><h3>Radial probability · n = {n}, l = {l}</h3><svg viewBox=\"0 0 420 130\" role=\"img\" aria-label=\"Relative radial probability distribution\" className=\"af-atomic-radial\"><path d=\"M35 15V105H400\" fill=\"none\" stroke=\"#64748b\"/><path d={radial.map((p,i)=>`${i?'L':'M'}${35+p.r/(10*n)*365} ${105-p.d/maxD*80}`).join(' ')} fill=\"none\" stroke=\"#4f46e5\" strokeWidth=\"3\"/><text x=\"38\" y=\"125\" fontSize=\"12\">0</text><text x=\"285\" y=\"125\" fontSize=\"12\">r / a₀ → {10*n}</text></svg></section>}\n    </>}\n  </div>;\n}\n", "src/components/simulation/BohrRadiationLab.tsx": "'use client';\nimport {useEffect,useRef,useState} from 'react';\nimport {bohrEnergy,bohrRadius,bohrVelocity,transitionWavelength,wavelengthToRGB,type AtomicParams} from '@/lib/physics/atomicModels';\nimport {advanceMotion,beginTransition,displayOrbit,effectiveCharge,fineSeparation,initialMotion,movingRadius,zeemanShifts} from '@/lib/physics/atomicExtensions';\nimport {viewZoom} from '@/lib/physics/bohrWorkbench';\nimport {BohrCalculations} from './BohrCalculations';\ntype Stats={energy:number;radius:number;velocity:number;n:number;wavelength:number;shellConfig:string};\ntype Props={params:AtomicParams;interactive?:boolean;viewReset?:number;isRunning?:boolean;isPaused?:boolean;controls?:{run:()=>void;pause:()=>void;reset:()=>void};onTick?:(s:Stats)=>void};\ntype Snapshot={n:number;from:number;to:number;kind:'orbit'|'absorption'|'emission';transitioning:boolean;wavelength:number};\nconst initialSnapshot:Snapshot={n:1,from:1,to:3,kind:'orbit',transitioning:false,wavelength:0};\nconst lightColour=(wl:number)=>wl<380?'#7c3aed':wl>780?'#b45309':wavelengthToRGB(wl);\nexport function BohrRadiationLab({params:p,interactive=true,viewReset=0,isRunning=false,isPaused=false,controls,onTick}:Props){\n const canvas=useRef<HTMLCanvasElement>(null),wrap=useRef<HTMLDivElement>(null),motion=useRef(initialMotion()),pan=useRef({x:0,y:0}),drag=useRef<{x:number;y:number;pan:{x:number;y:number}}|null>(null);\n const photons=useRef<{x:number;y:number;angle:number;life:number;wavelength:number}[]>([]),pending=useRef(0),autoTime=useRef(0);\n const [target,setTarget]=useState(3),[auto,setAuto]=useState(true),[snap,setSnap]=useState<Snapshot>(initialSnapshot);\n const props=useRef({p,isRunning,isPaused,onTick,auto});props.current={p,isRunning,isPaused,onTick,auto};\n const {sigma,Zeff}=effectiveCharge(p.protonCount||1,p.screening),Z=p.protonCount||1;\n useEffect(()=>{pan.current={x:0,y:0};},[viewReset]);\n useEffect(()=>{motion.current={...motion.current,transition:null};photons.current=[];autoTime.current=0;setSnap(s=>({...s,transitioning:false,wavelength:0}));},[Z,sigma]);\n useEffect(()=>{\n  const element=canvas.current,box=wrap.current;if(!element||!box)return;\n  let frame=0,last:number|null=null,lastReport=0;let latest={...initialSnapshot};\n  function draw(now:number){\n   const el=element!,container=box!,ctx=el.getContext('2d');if(!ctx)return;\n   const {p,isRunning,isPaused,onTick,auto}=props.current,q=effectiveCharge(p.protonCount||1,p.screening).Zeff;\n   const {width:w,height:h}=container.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);\n   if(w<1||h<1){frame=requestAnimationFrame(draw);return;}\n   const cw=Math.round(w*dpr),ch=Math.round(h*dpr);if(el.width!==cw||el.height!==ch){el.width=cw;el.height=ch;}ctx.setTransform(dpr,0,0,dpr,0,0);\n   const elapsed=last===null?0:Math.min(.05,(now-last)/1000);last=now;const dt=isRunning&&!isPaused?elapsed:0;\n   const R=Math.max(20,Math.min(w,h)*.43),cx=w/2,cy=h/2;\n   if(pending.current){motion.current=beginTransition(motion.current,pending.current);pending.current=0;autoTime.current=0;}\n   if(dt>0&&p.showElectrons){\n    if(!motion.current.transition&&auto){autoTime.current+=dt*p.speed;if(autoTime.current>2.8){autoTime.current=0;const current=motion.current.n;let to=Math.max(1,Math.min(7,current+(Math.random()<.5?-1:1)*(1+Math.floor(Math.random()*2))));if(to===current)to=current===1?3:1;motion.current=beginTransition(motion.current,to);}}\n    const result=advanceMotion(motion.current,dt,p.speed);motion.current=result.state;\n    if(result.completed){const t=result.completed,wl=transitionWavelength(t.from,t.to,q);latest={n:t.to,from:t.from,to:t.to,kind:t.to<t.from?'emission':'absorption',transitioning:false,wavelength:wl};\n     if(t.to<t.from){const r=displayOrbit(t.to,R,q);photons.current.push({x:cx+Math.cos(t.angle)*r,y:cy+Math.sin(t.angle)*r,angle:t.angle+1.1+Math.random()*.7,life:1,wavelength:wl});}autoTime.current=0;\n    }\n    photons.current=photons.current.map(ray=>({...ray,x:ray.x+Math.cos(ray.angle)*180*dt*p.speed,y:ray.y+Math.sin(ray.angle)*180*dt*p.speed,life:ray.life-dt*p.speed*.4})).filter(ray=>ray.life>0);\n   }\n   const s=motion.current,t=s.transition,angle=t?.angle??s.angle;\n   if(t)latest={n:s.n,from:t.from,to:t.to,kind:t.to<t.from?'emission':'absorption',transitioning:true,wavelength:transitionWavelength(t.from,t.to,q)};\n   else latest={...latest,n:s.n,transitioning:false,wavelength:latest.wavelength?transitionWavelength(latest.from,latest.to,q):0};\n   ctx.clearRect(0,0,w,h);ctx.fillStyle='#f8fafc';ctx.fillRect(0,0,w,h);\n   ctx.save();ctx.translate(cx+pan.current.x,cy+pan.current.y);ctx.scale(viewZoom(p.zoom),viewZoom(p.zoom));ctx.translate(-cx,-cy);\n   if(p.showOrbits)for(let n=1;n<=7;n++){const r=displayOrbit(n,R,q);ctx.strokeStyle=n===s.n?'#2563eb':'#94a3b8';ctx.lineWidth=n===s.n?2.5:1.1;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.stroke();if(p.showLabels&&w>=420){const a=n%2?-.6:Math.PI+.6,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;ctx.fillStyle='#f8fafc';ctx.fillRect(x-14,y-9,28,18);ctx.fillStyle=n===s.n?'#1d4ed8':'#334155';ctx.font='600 12px system-ui';ctx.textAlign='center';ctx.fillText(`n=${n}`,x,y+4);}}\n   if((p.screening||0)>0){const g=ctx.createRadialGradient(cx,cy,7,cx,cy,34);g.addColorStop(0,'rgba(59,130,246,.03)');g.addColorStop(.65,`rgba(59,130,246,${.12+Math.min(.3,(p.screening||0)/(p.protonCount||1)*.3)})`);g.addColorStop(1,'rgba(59,130,246,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(cx,cy,34,0,Math.PI*2);ctx.fill();}\n   if(p.showNucleus){ctx.fillStyle='#f59e0b';ctx.strokeStyle='#92400e';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(cx,cy,7,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#78350f';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText('+',cx,cy+4);}\n   const r=t?movingRadius(t.from,t.to,t.progress,R,q):displayOrbit(s.n,R,q),ex=cx+Math.cos(angle)*r,ey=cy+Math.sin(angle)*r;\n   if(t){const r1=displayOrbit(t.from,R,q),r2=displayOrbit(t.to,R,q);ctx.strokeStyle=t.to>t.from?'#c2410c':'#7c3aed';ctx.setLineDash([5,4]);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx+Math.cos(angle)*r1,cy+Math.sin(angle)*r1);ctx.lineTo(cx+Math.cos(angle)*r2,cy+Math.sin(angle)*r2);ctx.stroke();ctx.setLineDash([]);\n    if(t.to>t.from&&t.progress<.3){const endX=cx+Math.cos(angle)*r1,endY=cy+Math.sin(angle)*r1,pr=t.progress/.3;const sx=endX-R*.8,sy=endY-R*.55,px=sx+(endX-sx)*pr,py=sy+(endY-sy)*pr,a=Math.atan2(endY-sy,endX-sx);ctx.strokeStyle='#c2410c';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(px-Math.cos(a)*14,py-Math.sin(a)*14);ctx.lineTo(px+Math.cos(a)*14,py+Math.sin(a)*14);ctx.stroke();}\n   }\n   if(p.showElectrons){ctx.fillStyle='#2563eb';ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ex,ey,7,0,Math.PI*2);ctx.fill();ctx.stroke();if(p.showSpin){ctx.fillStyle='#be123c';ctx.font='bold 19px system-ui';ctx.textAlign='center';ctx.fillText('↑',ex,ey-14);}}\n   photons.current.forEach(ray=>{ctx.globalAlpha=Math.max(0,ray.life);ctx.strokeStyle=lightColour(ray.wavelength);ctx.lineWidth=3.5;ctx.beginPath();ctx.moveTo(ray.x-Math.cos(ray.angle)*15,ray.y-Math.sin(ray.angle)*15);ctx.lineTo(ray.x+Math.cos(ray.angle)*15,ray.y+Math.sin(ray.angle)*15);ctx.stroke();ctx.globalAlpha=1;});ctx.restore();\n   if(now-lastReport>90){lastReport=now;setSnap({...latest});onTick?.({n:s.n,energy:bohrEnergy(s.n,q),radius:bohrRadius(s.n,q),velocity:bohrVelocity(s.n,q)/2.998e8,wavelength:latest.wavelength,shellConfig:''});}\n   frame=requestAnimationFrame(draw);\n  }\n  frame=requestAnimationFrame(draw);return()=>cancelAnimationFrame(frame);\n },[]);\n const pairLow=Math.min(snap.from,snap.to),pairHigh=Math.max(snap.from,snap.to),inspectN=Math.max(2,snap.n),fine=fineSeparation(inspectN,Zeff),zeeman=5.788e-5*p.magneticField;\n return <section className=\"af-bohr-lesson af-bohr-original\" aria-label=\"Original Bohr orbital simulation\">\n  {interactive&&<header className=\"af-original-transport\"><button type=\"button\" onClick={isRunning?controls?.pause:controls?.run}>{!isRunning?'Run':isPaused?'Resume':'Pause'}</button><button type=\"button\" onClick={controls?.reset}>Reset</button><label><input type=\"checkbox\" checked={auto} onChange={e=>setAuto(e.target.checked)}/> Auto transitions</label><label>Target n<select aria-label=\"Transition target\" value={target} onChange={e=>{const to=Number(e.target.value);setTarget(to);}}>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>{n}</option>)}</select></label><button type=\"button\" disabled={snap.transitioning||target===snap.n||!p.showElectrons} onClick={()=>{pending.current=target;if(!isRunning||isPaused)controls?.run();}}>Transition</button><strong>{snap.transitioning?`${snap.kind==='absorption'?'Absorbing':'Emitting'} · n=${snap.from} → ${snap.to}`:`Orbiting state n=${snap.n}`}</strong></header>}\n  <div className=\"af-original-physics\"><span>Zeff = Z − σ = <strong>{Z} − {sigma.toFixed(2)} = {Zeff.toFixed(2)}</strong></span>{p.showZeeman&&<span>Zeeman μB·B = <strong>{(zeeman*1e6).toFixed(2)} μeV</strong></span>}{p.showFineStructure&&<span>Fine split n={inspectN}: <strong>{(fine*1e6).toFixed(2)} μeV</strong></span>}<span>λ: <strong>{snap.wavelength?snap.wavelength.toFixed(2)+' nm':'—'}</strong></span></div>\n  <div className=\"af-bohr-workspace\"><div className=\"af-bohr-diagrams\" data-levels={p.showEnergyLevels}>\n   <figure className=\"af-bohr-atom\"><figcaption>Bohr orbits · n={snap.n}<small>Drag to pan · straight transition paths are schematic</small></figcaption><div className=\"af-original-canvas\" ref={wrap}><canvas ref={canvas} role=\"img\" aria-label={`Electron orbiting nucleus Z=${Z}; effective charge ${Zeff.toFixed(2)}; current state n=${snap.n}`} onPointerDown={e=>{drag.current={x:e.clientX,y:e.clientY,pan:{...pan.current}};e.currentTarget.setPointerCapture(e.pointerId);}} onPointerMove={e=>{const d=drag.current;if(d)pan.current={x:d.pan.x+e.clientX-d.x,y:d.pan.y+e.clientY-d.y};}} onPointerUp={()=>{drag.current=null;}} onPointerCancel={()=>{drag.current=null;}}/></div></figure>\n   {p.showEnergyLevels&&<figure className=\"af-bohr-energy af-original-levels\"><figcaption>Energy levels<small>Level spacing schematic · splitting enlarged</small></figcaption><div className=\"af-original-level-list\">{[7,6,5,4,3,2,1].map(n=><div className=\"af-original-level\" key={n} data-active={n===snap.n}><span>n={n}</span><svg viewBox=\"0 0 80 28\" role=\"img\" aria-label={`n=${n}: ${bohrEnergy(n,Zeff).toFixed(4)} eV${p.showZeeman&&n>1?'; Zeeman triplet enlarged':''}`}><line x1=\"2\" x2=\"78\" y1=\"14\" y2=\"14\" stroke=\"#94a3b8\" strokeWidth={n===snap.n?2.5:1}/>{p.showFineStructure&&n>1&&[-1,1].map(sign=><line key={sign} x1=\"3\" x2=\"34\" y1={14+sign*3} y2={14+sign*3} stroke=\"#2563eb\" strokeWidth=\"2\"/>)}{p.showZeeman&&n>1&&[-1,0,1].map(m=><line key={m} x1=\"42\" x2=\"78\" y1={14-m*p.magneticField*1.5} y2={14-m*p.magneticField*1.5} stroke=\"#a21caf\" strokeWidth=\"2\"/>)}</svg><strong>{Math.abs(bohrEnergy(n,Zeff))<10000?bohrEnergy(n,Zeff).toFixed(3):bohrEnergy(n,Zeff).toExponential(2)}</strong></div>)}</div><p>eV · blue: fine · magenta: normal Zeeman. Separate schematic illustrations.</p></figure>}\n   </div><BohrCalculations lower={pairLow} upper={pairHigh} Z={Zeff} n={snap.n} emission={snap.kind==='emission'} missed={false} chargeSymbol={sigma>0?'Zeff':'Z'} photonEnergy={Math.abs(bohrEnergy(snap.to,Zeff)-bohrEnergy(snap.from,Zeff))}/></div>\n  {p.showSpectrum&&<section className=\"af-original-spectrum\" aria-label=\"Emission spectrum\"><span>Visible reference · last λ {snap.wavelength?snap.wavelength.toFixed(1):'—'} nm</span><div className=\"af-original-spectrum-track\">{Array.from({length:41},(_,i)=>380+i*10).map(wl=><i key={wl} style={{left:((wl-380)/400*100)+'%',background:wavelengthToRGB(wl)}}/>)}{snap.kind==='emission'&&snap.wavelength>=380&&snap.wavelength<=780&&<b style={{left:((snap.wavelength-380)/400*100)+'%'}}/>}</div>{p.showZeeman&&<div className=\"af-original-zeeman-spectrum\"><span>Normal-Zeeman triplet · enlarged</span><svg viewBox=\"0 0 180 22\" role=\"img\" aria-label={`Three line shifts: ${zeemanShifts(p.magneticField).map(s=>(s.shift*1e6).toFixed(2)).join(', ')} microelectronvolts`}>{[-1,0,1].map(m=><line key={m} x1={90+m*p.magneticField*12} x2={90+m*p.magneticField*12} y1=\"2\" y2=\"20\" stroke=\"#a21caf\" strokeWidth=\"3\"/>)}</svg></div>}</section>}\n  <footer className=\"af-bohr-narration\"><strong>{snap.transitioning?`${snap.kind==='absorption'?'Energy absorbed':'Energy released'} · n=${snap.from} → ${snap.to}`:'Circular motion in an allowed Bohr orbit'}</strong><small>Orbit spacing and transition paths are schematic. Screening uses a chosen σ in a hydrogenic approximation; normal Zeeman and fine-structure illustrations are separate. UV/IR rays use false colour.</small></footer>\n </section>;\n}\n", "src/components/simulation/BohrCalculations.tsx": "import {bohrWorkings,scientific,PLANCK_EV_SECONDS} from '@/lib/physics/bohrWorkbench';\nexport function BohrCalculations({lower,upper,Z,n,emission,missed,photonEnergy,chargeSymbol='Z'}:{lower:number;upper:number;Z:number;n:number;emission:boolean;missed:boolean;photonEnergy?:number;chargeSymbol?:'Z'|'Zeff'}){\n const c=bohrWorkings(lower,upper,Z,n,emission),sign=(v:number)=>(v>0?'+':'')+v.toFixed(4);\n const supplied=photonEnergy??c.photon, displayZ=Number(Z.toFixed(6));\n const short=['Eᵢ','E𝒇','ΔE atom',emission?'Eγ emitted':'Eγ absorbed','ν photon','λ photon','rₙ','vₙ'];\n const rows=[\n  ['Initial energy Eᵢ',`−13.606 × ${displayZ}² / ${c.from}²`,`${c.Ei.toFixed(4)} eV`],\n  [missed?'Target energy (not reached)':'Final energy E𝒇',`−13.606 × ${displayZ}² / ${c.to}²`,`${c.Ef.toFixed(4)} eV`],\n  ['Atom ΔE = E𝒇 − Eᵢ',missed?'No absorption':`${c.Ef.toFixed(4)} − (${c.Ei.toFixed(4)})`,`${missed?'0.0000':sign(c.delta)} eV`],\n  [emission?'Photon emitted Eγ':'Photon absorbed Eγ',`Required gap: ${c.photon.toFixed(4)} eV`,`${supplied.toFixed(4)} eV`],\n  ['Frequency ν = Eγ / h',`${supplied.toFixed(4)} / 4.135668×10⁻¹⁵`,`${scientific(supplied/PLANCK_EV_SECONDS)} Hz`],\n  ['Wavelength λ ≈ 1240 / Eγ',`1240 / ${supplied.toFixed(4)}`,`${(1240/supplied).toFixed(2)} nm`],\n  [`Live radius rₙ = 0.529 n²/${chargeSymbol}`,`0.529 × ${n}² / ${displayZ}`,`${c.radius.toFixed(3)} Å`],\n  [`Live speed vₙ ≈ 2.188×10⁶ ${chargeSymbol}/n`,`2.188×10⁶ × ${displayZ} / ${n}`,`${scientific(c.velocity)} m/s`],\n ];\n return <aside className=\"af-bohr-calculations\" aria-label=\"Live worked calculations\"><h3>{missed?'No absorption':emission?'Emission':'Excitation'} · worked calculation</h3><div className=\"af-bohr-calculation-grid\">{rows.map(([title,expression,result],i)=><div className=\"af-bohr-calculation\" role=\"group\" aria-label={`${title}: ${result}`} title={`${title}: ${expression} = ${result}`} key={title}><span className=\"af-calc-long\">{title}</span><span className=\"af-calc-short\">{short[i]}</span><code>{expression}</code><strong>{result}</strong></div>)}</div><p className=\"af-bohr-ledger\">Now: <strong>n={n}</strong> · Eₙ=<strong>{c.currentEnergy.toFixed(3)} eV</strong><br/>Stored above n={lower}: <strong>{c.stored.toFixed(3)} eV</strong>{missed&&<span> · No photon absorbed; actual transfer = 0.</span>}<small className=\"af-bohr-rounding\">Rounded display; calculations use full precision.</small></p></aside>;\n}\n", "src/components/simulation/atomic-models.css": ".af-atomic-view { color-scheme:light; color:#0f172a; background:#fff; border:1px solid #cbd5e1; border-radius:14px; overflow:hidden; min-width:0; display:flex; flex-direction:column; }\n.af-atomic-view :is(button,select) { font:inherit; font-size:13px; min-height:40px; padding:7px 10px; border:1px solid #cbd5e1; border-radius:8px; background:white; color:#0f172a; max-width:100%; }\n.af-atomic-view button { cursor:pointer; }\n.af-atomic-view button:disabled { opacity:.45; cursor:default; }\n.af-atomic-view :is(button,select):focus-visible { outline:3px solid #2563eb; outline-offset:2px; }\n.af-atomic-toolbar { display:flex; align-items:center; flex-wrap:wrap; gap:10px; padding:10px 14px; border-bottom:1px solid #cbd5e1; background:#f8fafc; flex:0 0 auto; }\n.af-atomic-toolbar>strong { font-size:14px; margin-right:auto; }\n.af-atomic-toolbar label { display:flex; align-items:center; gap:7px; font-size:12px; font-weight:600; }\n.af-atomic-playback { display:flex; gap:6px; }\n.af-atomic-layout { display:flex; flex:1; min-height:0; min-width:0; }\n.af-atomic-scene { position:relative; width:100%; height:clamp(320px,48vw,620px); min-width:0; overflow:hidden; background:#f8fafc; }\n.af-atomic-scene canvas { display:block; width:100%; height:100%; }\n.af-atomic-notes { padding:12px 18px; background:#fff1f2; border-top:1px solid #fecdd3; flex:0 0 auto; }\n.af-atomic-view h3 { margin:0 0 6px; font-size:16px; font-weight:700; }\n.af-atomic-view p { font-size:14px; line-height:1.5; margin:5px 0; }\n.af-atomic-view .af-atomic-caption { font-size:12px; color:#475569; }\n.af-atomic-legend { font-weight:600; color:#334155; }\n.af-atomic-radial { display:block; width:100%; max-width:420px; height:100px; fill:#334155; }\n.af-bohr-lesson { display:flex; flex-direction:column; min-height:0; min-width:0; flex:1; background:#fff; }\n.af-bohr-controls { display:flex; align-items:center; fle